import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_SIZE = 21;
    static final double TOLERANCE = 1e-6;
    static int count = 0, k_value, m_value;
    static double[] prob = new double[MAX_SIZE];
    static int[] idx = new int[MAX_SIZE];
    static double[] dp = new double[1 << MAX_SIZE];
    static double[] answer = new double[MAX_SIZE];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        m_value = Integer.parseInt(st.nextToken());
        k_value = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < m_value; i++) {
            double val = Double.parseDouble(st.nextToken());
            if (val > TOLERANCE) {
                prob[count] = val;
                idx[count] = i;
                count++;
            } else {
                answer[i] = 0.0;
            }
        }

        if (k_value >= count) {
            for (int i = 0; i < count; i++) {
                answer[idx[i]] = 1.0;
            }
        } else {
            Arrays.fill(dp, 0.0);
            dp[0] = 1.0;
            int totalMasks = 1 << count;
            for (int mask = 0; mask < totalMasks; mask++) {
                if (Integer.bitCount(mask) < k_value) {
                    double sum_p = 0.0;
                    for (int t = 0; t < count; t++) {
                        if (((mask >> t) & 1) == 0) {
                            sum_p += prob[t];
                        }
                    }
                    if (sum_p > 0) {
                        for (int t = 0; t < count; t++) {
                            if (((mask >> t) & 1) == 0) {
                                int nextMask = mask | (1 << t);
                                dp[nextMask] += (prob[t] / sum_p) * dp[mask];
                            }
                        }
                    }
                }
            }
            for (int mask = 0; mask < totalMasks; mask++) {
                if (Integer.bitCount(mask) == k_value) {
                    for (int t = 0; t < count; t++) {
                        if (((mask >> t) & 1) == 1) {
                            answer[idx[t]] += dp[mask];
                        }
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m_value; i++) {
            sb.append(answer[i]).append(" ");
        }
        System.out.println(sb.toString().trim());
    }
}
